{"name":"aceptar_invitacion","owner":"postgres","schema":"public","arguments":"p_invitacion uuid","definition":"CREATE OR REPLACE FUNCTION public.aceptar_invitacion(p_invitacion uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
  v_comunidad uuid;
begin
  update public.invitaciones set estado = 'aceptada'
  where id = p_invitacion
    and estado = 'pendiente'
    and correo = lower(auth.jwt() ->> 'email')
  returning comunidad_id into v_comunidad;

  if v_yo is null or v_comunidad is null then
    raise exception 'La invitación no existe o ya fue usada' using errcode = 'P0002';
  end if;

  insert into public.miembros (comunidad_id, usuario_id) values (v_comunidad, v_yo)
  on conflict do nothing;
  update public.perfiles set comunidad_activa = v_comunidad where id = v_yo;
  return v_comunidad;
end;
$function$
","execute_anon":true,"execute_authenticated":true}

{"name":"crear_comunidad","owner":"postgres","schema":"public","arguments":"p_nombre text, p_lat double precision, p_lng double precision, p_zona_nombre text","definition":"CREATE OR REPLACE FUNCTION public.crear_comunidad(p_nombre text, p_lat double precision, p_lng double precision, p_zona_nombre text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
  v_id uuid;
begin
  if v_yo is null then
    raise exception 'Debes iniciar sesión' using errcode = '42501';
  end if;

  insert into public.comunidades (nombre, zona, zona_nombre, creada_por)
  values (
    trim(p_nombre),
    extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography,
    nullif(trim(p_zona_nombre), ''),
    v_yo
  )
  returning id into v_id;

  insert into public.miembros (comunidad_id, usuario_id, rol) values (v_id, v_yo, 'admin');
  update public.perfiles set comunidad_activa = v_id where id = v_yo;
  return v_id;
end;
$function$
","execute_anon":true,"execute_authenticated":true}

{"name":"crear_perfil_nuevo_usuario","owner":"postgres","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.crear_perfil_nuevo_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_nombre text := left(trim(coalesce(new.raw_user_meta_data ->> 'nombre', '')), 60);
begin
  if char_length(v_nombre) < 2 then
    v_nombre := 'Vecino';
  end if;
  insert into public.perfiles (id, nombre) values (new.id, v_nombre);
  insert into public.perfiles_privado (id) values (new.id);
  return new;
end;
$function$
","execute_anon":true,"execute_authenticated":true}

{"name":"unirse_con_codigo","owner":"postgres","schema":"public","arguments":"p_codigo text","definition":"CREATE OR REPLACE FUNCTION public.unirse_con_codigo(p_codigo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
  v_id uuid;
begin
  if v_yo is null then
    raise exception 'Debes iniciar sesión' using errcode = '42501';
  end if;

  select id into v_id from public.comunidades
  where codigo_invitacion = upper(trim(p_codigo));

  if v_id is null then
    raise exception 'El código no es válido' using errcode = 'P0002';
  end if;

  insert into public.miembros (comunidad_id, usuario_id) values (v_id, v_yo)
  on conflict do nothing;

  update public.invitaciones set estado = 'aceptada'
  where comunidad_id = v_id and correo = lower(auth.jwt() ->> 'email') and estado = 'pendiente';

  update public.perfiles set comunidad_activa = v_id where id = v_yo;
  return v_id;
end;
$function$
","execute_anon":true,"execute_authenticated":true}
